const staticResponse=(text,type)=>new Response(text,{status:200,headers:{'content-type':type,'cache-control':'public, max-age=180','x-content-type-options':'nosniff'}});
export default {
 async fetch(request) {
  const url=new URL(request.url);
  const path=decodeURIComponent(url.pathname).replace(/\/+$/,'')||'/';
  if(path==='/style.css')return staticResponse(CSS,'text/css; charset=utf-8');
  if(path==='/scene.js')return staticResponse(THREE_SCENE,'text/javascript; charset=utf-8');
  if(path==='/favicon.svg')return staticResponse('<svg xmlns="http://www.w3.org/2000/svg" viewBox="0 0 64 64"><rect width="64" height="64" rx="18" fill="#d6f8fc"/><path d="M18 10c35 12 35 32 0 44M46 10C11 22 11 42 46 54M24 22h16M20 32h24M24 42h16" stroke="#168da2" stroke-width="4" fill="none" stroke-linecap="round"/></svg>','image/svg+xml');
  if(path==='/robots.txt')return staticResponse('User-agent: *\nDisallow: /\n','text/plain; charset=utf-8');
  if(path==='/'||path==='/index.html')return staticResponse(layout(home(),'صفحه اصلی'),'text/html; charset=utf-8');
  if(path==='/about')return staticResponse(layout(about(),'درباره استودیو'),'text/html; charset=utf-8');
  const segments=path.split('/').filter(Boolean);
  const c=DATA.collections.find(x=>x.id===segments[0]);
  if(c&&segments.length===1)return staticResponse(layout(listing(c),c.title),'text/html; charset=utf-8');
  if(c&&segments.length===2){const item=DATA.entries.find(x=>x[0]===c.id&&x[1]===segments[1]);if(item)return staticResponse(layout(detail(item,c),item[2]),'text/html; charset=utf-8');}
  return new Response(layout('<main id="main-content" class="site-container missing-main"><div class="glass-panel missing-card"><p class="eyebrow">404 / ARCHIVE NOT FOUND</p><h1>این صفحه پیدا نشد.</h1><p>ممکن است نشانی تغییر کرده باشد.</p><a href="/" class="button-primary">بازگشت به صفحه اصلی</a></div></main>','صفحه پیدا نشد'),{status:404,headers:{'content-type':'text/html; charset=utf-8','x-robots-tag':'noindex'}});
 }
};
